UPDATE sys_flow_notify_outbox
SET delivery_status = 2,
    delivered_time = #{now},
    next_retry_time = NULL,
    lock_owner = NULL,
    lock_time = NULL,
    last_error = NULL,
    update_time = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND delivery_status = 1
  AND lock_owner = #{lockOwner}

UPDATE sys_flow_notify_outbox
SET delivery_status = #{deliveryStatus},
    next_retry_time = #{nextRetryTime},
    lock_owner = NULL,
    lock_time = NULL,
    last_error = #{lastError},
    update_time = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND delivery_status = 1
  AND lock_owner = #{lockOwner}
